\section{Preliminaries}

For any two sets $A$ and $B$ such that $A\cap B=\emptyset$, we use the notation $A\sqcup B$ to denote the union $A\cup B$, while emphasizing the fact that $A\cap B=\emptyset$.

If $L$ is a sorted list of elements and $x$ is an element in $L$, we use $\mathit{next}_L(x)$ and $\mathit{prev}_L(x)$ to denote the successor and the predecessor, respectively, of $x$ in $L$. We use $\bot$ to denote the end-of-list element. A \emph{segment} of $L$ is a sublist of consecutive elements. For convenience, we may handle a list as set (and write, e.g., $x\in L$).

\section{Concepts defined on DFS-tree}

Throughout this chapter we assume that $G$ is a connected graph with $n$ vertices and $m$ edges, and $r$ is a vertex of $G$.

Let $T$ be a DFS-tree of $G$ with start vertex $r$. We identify the vertices of $G$ with their order of visit by the DFS. For a vertex $v\neq r$ of $G$, we let $p(v)$ denote the parent of $v$ on $T$. If $v$ lies on the tree-path $T[r,u]$, then we say that $v$ is an ancestor of $u$ (equivalently, $u$ is a descendant of $v$). If $v$ is an ancestor of $u$ such that $v\neq u$, then we say that $v$ is a proper ancestor of $u$ (equivalently, $u$ is a proper descendant of $v$). We let $T(v)$ denote the set of descendants of a vertex $v$.

Whenever we let $(x,y)$ denote a back-edge, we always assume that $x$ is the higher endpoint of $(x,y)$ (i.e., $x>y$). For a vertex $v\neq r$, we say that a back-edge $(x,y)$ leaps over $v$ if $x$ is a descendant of $v$ and $y$ is a proper ancestor of $v$. We let $B(v)$ denote the set of the back-edges that leap over $v$. 

Let $v\neq r$ be a vertex. We let $\mathit{bcount}(v)$ denote the number of back-edges that leap over $v$ (i.e., $\mathit{bcount}(v)=|B(v)|$).

Now let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in increasing order w.r.t. their lower endpoint. Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{low}_i$-edge of $v$. The lower endpoint of the $\mathit{low}_i$-edge of $v$ is called the $\mathit{low}_i$ point of $v$, and we denote it as $\mathit{low}_i(v)$. Of particular importance is the $\mathit{low}_1$ point of $v$, which we may simply denote as $\mathit{low}(v)$.

Now let $v\neq r$ be a vertex, and let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in decreasing order w.r.t. their lower endpoint. Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{high}_i$-edge of $v$. The lower endpoint of the $\mathit{high}_i$-edge of $v$ is called the $\mathit{high}_i$ point of $v$, and we denote it as $\mathit{high}_i(v)$. Of particular importance is the $\mathit{high}_1$ point of $v$, which we may simply denote as $\mathit{high}(v)$. Also, we denote the $\mathit{high}_1$-edge of $v$ as $e_\mathit{high}(v)$.

Let $v\neq r$ be a vertex. We let $M(v)$ denote the maximum vertex that is an ancestor of the higher endpoints of the back-edges in $B(v)$. For every vertex $x$, we let $M^{-1}(x)$ denote the list of all vertices $v$ with $M(v)=x$, sorted in decreasing order. We also let $\mathit{lastM}(v)$ denote the lowest vertex in $M^{-1}(M(v))$. 

We extend the concept of the $M$ points in general sets of back-edges. Thus, if $S$ is a set of back-edges, then we let $M(S)$ denote the nearest common ancestor of the higher endpoints of the back-edges in $S$.

\begin{lemma}
\label{lemma:same_m_same_low}
Let $v$ and $v'$ be two vertices such that $M(v)=M(v')$. Then $\mathit{low}(v)=\mathit{low}(v')$.
\end{lemma}

\begin{proposition}
\label{proposition:computing-M(B(v)-S)}
Let $(v_1,S_1),\dots,(v_N,S_N)$ be a collection of pairs of vertices and sets of back-edges, such that $v_i\neq r$ and $\emptyset\neq S_i\subseteq B(v_i)$ for every $i\in\{1,\dots,N\}$. Then the values $M(B(v_1)\setminus{S_1}),\dots,M(B(v_N)\setminus{S_N})$ can be computed in $O(m+|S_1|+\dots+|S_N|)$ time in total.
\end{proposition}

For every vertex $x$, we also define the list $\widetilde{H}(x)$ that consists of all vertices $v\neq r$ such that either $\mathit{high}_1(v)=x$ or $\mathit{high}_2(v)=x$, sorted in decreasing order. For every vertex $v\neq r$, we let $\widetilde{S}_1(v)$ denote the segment of $\widetilde{H}(\mathit{high}_1(v))$ that contains $v$ and is maximal w.r.t. the property that its elements are related as ancestor and descendant. Similarly, we let $\widetilde{S}_2(v)$ denote the segment of $\widetilde{H}(\mathit{high}_2(v))$ that contains $v$ and is maximal w.r.t. the property that its elements are related as ancestor and descendant.

\section{Computing a complete collection of $4$-cuts}

\subsection{Min-max vertex queries}

We are given a collection $W_1,\dots,W_k$ of pairwise disjoint sets of vertices, and a set of $N$ queries of the form $q(i,z)\equiv$ ``given an index $i\in\{1,\dots,k\}$ and a vertex $z$, find the greatest vertex $w\in W_i$ such that $w\leq z$". We can answer all those queries simultaneously, in $O(n+N)$ time in total. 

\begin{lemma}
\label{lemma:W-queries}
Let $W_1,\dots,W_k$ be a collection of pairwise disjoint sets of vertices. Let $q(i_1,z_1),\dots,q(i_N,z_N)$ be a set of queries of the form $q(i,z)\equiv$`` given an index $i\in\{1,\dots,k\}$ and a vertex $z$, find the greatest vertex $w\in W_i$ such that $w\leq z$". Then, Algorithm~\ref{algorithm:W-queries} answers all those queries in $O(n+N)$ time. 
\end{lemma}

\begin{algorithm}[t!]
\caption{\textsf{Given a collection $W_1,\dots,W_k$ of pairwise disjoint sets of vertices, answer a set of queries $q(i_1,z_1),\dots,q(i_N,z_N)$, where $q(i_t,z_t)$, for every $t\in\{1,\dots,N\}$, asks for the greatest vertex $w\in W_{i_t}$ such that $w\leq z_t$.}}
\label{algorithm:W-queries}
\LinesNumbered
\DontPrintSemicolon
\tcp{$W_1,\dots,W_k$ is a collection of pairwise disjoint sets of vertices}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $W_i$ in decreasing order\;
}
\ForEach{$i\in\{1,\dots,k\}$}{
  initialize $Q(i)\leftarrow\emptyset$\;
}
\ForEach{$t\in\{1,\dots,N\}$}{
  insert a tuple $(z_t,t)$ into $Q(i_t)$\;
}
\tcp{$Q(i)$ contains a tuple of the form $(z,t)$ if and only if the query $q(i_t,z_t)$ has $i_t=i$ and $z_t=z$. The first component of a tuple in $Q(i)$ stores the vertex of the respective query, and the second component stores a pointer to the query. The information, that we have to search in the set $W_i$ for the answer to this query, is given precisely by the index $i$ of this bucket of tuples}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $Q(i)$ in decreasing order w.r.t. the first component of its elements\; 
}
\ForEach{$i\in\{1,\dots,k\}$}{
\label{line:W-queries-for}
  let $w$ be the first element of $W_i$\;
  let $p$ be the first element of $Q(i)$\;
  \While{$p\neq\bot$}{
    let $p=(z,t)$\;
    \While{$w\neq\bot$ \textbf{and} $w>z$}{
      $w\leftarrow\mathit{next}_{W_i}(w)$\;
    }
    the answer to $q(i_t,z_t)$ is $w$\;
    $p\leftarrow\mathit{next}_{Q(i)}(p)$\;
  }
}
\end{algorithm}

\section{Computing Type-3$\beta$ $4$-cuts}

Throughout this section, we assume that $G$ is a $3$-edge-connected graph with $n$ vertices and $m$ edges. All graph-related elements (e.g., vertices, edges, cuts, etc.) refer to $G$. Furthermore, we assume that we have computed a DFS-tree $T$ of $G$ rooted at a vertex $r$.

\begin{lemma}
\label{lemma:type-3b-cases}
Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$ and $v$ is a proper ancestor of $u$, and let $e$ be a back-edge. Then $C'=\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut if and only if one of the following is true. (See Figure~\ref{figure:type3b}.)
\begin{enumerate}[label=(\arabic*)]
\item{$e\in B(u)\cap B(v)\cap B(w)$ and $B(v)\setminus\{e\}=(B(u)\setminus\{e\})\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(w)$, $e\notin B(v)\cup B(u)$, and $B(v)=B(u)\sqcup(B(w)\setminus\{e\})$}
\item{$e\in B(u)$, $e\notin B(v)\cup B(w)$, and $B(v)=(B(u)\setminus\{e\})\sqcup B(w)$}
\item{$e\in B(v)$ and $B(v)=(B(u)\sqcup B(w))\sqcup\{e\}$}
\end{enumerate}
\end{lemma}

\subsection{Type-3$\beta ii$ $4$-cuts}

\subsubsection{Type-3$\beta ii$-$4$ $4$-cuts}

Let $u,v,w$ be three vertices $\neq r$ such that $w$ is proper ancestor of $v$, $v$ is a proper ancestor of $u$, and there is a back-edge $e\in B(v)$ such  $B(v)=(B(u)\sqcup B(w))\sqcup\{e\}$ and $M(B(v)\setminus\{e\})=M(w)$. By Lemma~\ref{lemma:type-3b-cases}, we have that $C=\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut, and we call this a Type-3$\beta$ii-$4$ $4$-cut.

\begin{lemma}
\label{lemma:type3-b-ii-4-info}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$4$ $4$-cut, and let $e$ be the back-edge in the $4$-cut induced by $(u,v,w)$. Then $w\leq\mathit{low}(u)$, and either $\mathit{high}_1(v)=\mathit{high}(u)$, or $\mathit{high}_1(v)>\mathit{high}(u)$ and $\mathit{high}_2(v)=\mathit{high}(u)$. If $\mathit{high}_1(v)\neq\mathit{high}(u)$, then $e=e_\mathit{high}(v)$.
\end{lemma}

\begin{lemma}
\label{lemma:type3-b-ii-4-seg-1}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$4$ $4$-cut, such that $\mathit{high}_1(v)\neq\mathit{high}(u)$. Let $u'$ be a vertex in $\widetilde{H}(\mathit{high}_2(v))$ such that $u\geq u'\geq v$. Then $u'$ is an ancestor of $u$. 
\end{lemma}

\noindent\\
\textbf{The case where $M(B(v)\setminus\{e\})= M(v)$ and $\mathit{high}_1(v)>\mathit{high}(u)$}\\

Now let $v\neq r$ be a vertex such that $\mathit{high}_1(v)\neq\mathit{high}_2(v)$ and $\mathit{lastM}(v)\leq\mathit{high}_2(v)$. We let $\widetilde{\mathit{nextM}}(v)$ denote the greatest proper ancestor $w$ of $\mathit{high}_1(v)$ such that $M(w)=M(v)$. 

Now let $S$ be the segment of $\widetilde{H}(\mathit{high}_2(v))$ that contains $v$ and is maximal w.r.t. the property that all its elements are related as ancestor and descendant (i.e., we have $S=\widetilde{S}_2(v)$). Then, we let $U_4^3(v)$ denote the collection of all vertices $u\in S$ such that: $(1)$ $u$ is a proper descendant of $v$ with $\mathit{high}(u)=\mathit{high}_2(v)$, $(2)$ $\mathit{low}(u)\geq\mathit{lastM}(v)$, and $(3)$ either $\mathit{low}(u)<\widetilde{\mathit{nextM}}(v)$, or $u$ is the lowest vertex in $S$ that satisfies $(1)$, $(2)$ and $\mathit{low}(u)\geq\widetilde{\mathit{nextM}}(v)$.

\begin{lemma}
\label{lemma:type-3bii-4-3-aux}
Let $v$ and $v'$ be two vertices $\neq r$ such that $v'$ is a proper descendant of $v$ with $\mathit{high}_1(v)\neq \mathit{high}_2(v)=\mathit{high}_2(v')\neq\mathit{high}_1(v')$. Let $w$ and $w'$ be two vertices such that $M(w)=M(v)$, $M(w')=M(v')$, and both $w$ and $w'$ are ancestors of $\mathit{high}_2(v)=\mathit{high}_2(v')$. Then $w'$ is a proper ancestor of $w$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute the sets $U_4^3(v)$, for all vertices $v\neq r$ such that $\mathit{high}_1(v)\neq\mathit{high}_2(v)$ and $\widetilde{\mathit{nextM}}(v)\neq\bot$}}
\label{algorithm:type3-b-ii-4-3-U}
\LinesNumbered
\DontPrintSemicolon
let $\mathcal{V}$ be the collection of all vertices $v\neq r$ such that $\mathit{high}_1(v)\neq\mathit{high}_2(v)$ and $\widetilde{\mathit{nextM}}(v)\neq\bot$\;
\ForEach{vertex $x$}{
  compute the collection $\mathcal{S}(x)$ of the segments of $\widetilde{H}(x)$ that are maximal w.r.t. the property
  that their elements are related as ancestor and descendant\;
}
\ForEach{$v\in\mathcal{V}$}{
  set $U_4^3(v)\leftarrow\emptyset$\;
}
\ForEach{vertex $x$}{
  \ForEach{segment $S\in\mathcal{S}(x)$}{
    let $v$ be the first vertex in $S$\;
    \While{$v\neq\bot$ \textbf{and} ($\mathit{high}_2(v)\neq x$ \textbf{or} $v\notin\mathcal{V}$)}{
    \label{line:type-3-b-ii-4-3-v-1}
      $v\leftarrow\mathit{next}_S(v)$\;
    }
    \lIf{$v=\bot$}{\textbf{continue}}
    let $u\leftarrow\mathit{prev}_S(v)$\;
    \While{$v\neq\bot$}{
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}(u)<\mathit{lastM}(v)$}{
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \While{$u\neq\bot$ \textbf{and} $\mathit{low}(u)<\widetilde{\mathit{nextM}}(v)$}{
        \If{$\mathit{high}_1(u)=x$}{
        \label{line:type-3-b-ii-4-3-u-1}
          insert $u$ into $U_4^3(v)$\;
        }
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \While{$u\neq\bot$ \textbf{and} $\mathit{high}_1(u)\neq x$}{
      \label{line:type-3-b-ii-4-3-u-2}
        $u\leftarrow\mathit{prev}_S(u)$\;
      }
      \If{$u\neq\bot$}{
        insert $u$ into $U_4^3(v)$\;
      }
      $v\leftarrow\mathit{next}_S(v)$\;
      \While{$v\neq\bot$ \textbf{and} ($\mathit{high}_2(v)\neq x$ \textbf{or}  $v\notin\mathcal{V}$)}{
      \label{line:type-3-b-ii-4-3-v-2}
        $v\leftarrow\mathit{next}_S(v)$\;
      }      
    }
  }
}
\end{algorithm}

\begin{lemma}
\label{lemma:algorithm:type3-b-ii-4-3-U}
Algorithm~\ref{algorithm:type3-b-ii-4-3-U} correctly computes the sets $U_4^3(v)$, for all vertices $v\neq r$ such that $\widetilde{\mathit{nextM}}(v)\neq\emptyset$. Furthermore, it runs in linear time.
\end{lemma}

\begin{lemma}
\label{lemma:type3-b-ii-4-3-criterion}
Let $(u,v,w)$ be a triple of vertices such that $\mathit{high}_1(v)>\mathit{high}(u)$, $M(B(v)\setminus\{e_\mathit{high}(v)\})= M(v)$ and $u\in U_4^3(v)$. Then, $(u,v,w)$ induces a Type-3$\beta$ii-$4$ $4$-cut if and only if: $\mathit{bcount}(v)=\mathit{bcount}(u)+\mathit{bcount}(w)+1$, and $w$ is the greatest proper ancestor of $v$ with $M(w)=M(v)$ such that $w\leq\mathit{low}(u)$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute all Type-3$\beta$ii-$4$ $4$-cuts of the form $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$, where $M(B(v)\setminus\{e\})= M(v)$ and $\mathit{high}_1(v)>\mathit{high}(u)$}}
\label{algorithm:type3-b-ii-4-3}
\LinesNumbered
\DontPrintSemicolon
let $\mathcal{V}$ be the collection of all vertices $v\neq r$ such that $M(B(v)\setminus\{e_\mathit{high}(v)\})=M(v)$, $\mathit{high}_1(v)\neq\mathit{high}_2(v)$ and $\mathit{lastM}(v)\leq\mathit{high}_2(v)$\;
\label{line:type4-b-ii-4-3-V}
\ForEach{$v\in\mathcal{V}$}{
  compute $U_4^3(v)$\;
  \label{line:type4-b-ii-4-3-U}
}
\ForEach{$v\in\mathcal{V}$}{
  \ForEach{$u\in U_4^3(v)$}{
    let $w$ be the greatest proper ancestor of $v$ with $M(w)=M(v)$ such that $w\leq\mathit{low}(u)$\;
    \label{line:type4-b-ii-4-3-w}    
    \If{$\mathit{bcount}(v)=\mathit{bcount}(u)+\mathit{bcount}(w)+1$ \textbf{and} $\mathit{high}_1(v)>\mathit{high}(u)$}{
      mark $\{(u,p(u)),(v,p(v)),(w,p(w)),e_\mathit{high}(v)\}$ as a Type-3$\beta$ii-$4$ $4$-cut\; 
      \label{line:type4-b-ii-4-3-mark}
    }
  }
}
\end{algorithm}
